/**
 * Wait for the compaction to end.
 *
 * Keyed on the event stream and not on `session.isCompacting`: every
 * `compaction_start` the host has been told about is followed by a
 * `compaction_end`, while Pi also counts a branch summarization as
 * compacting and announces neither end of it.
 */
private awaitCompactionEnd(record: ThreadRecord): Promise<void> {
  return new Promise<void>((resolve) => {
    record.compactionWaiters.add(resolve);
  });
}

/** Answer every prompt the host still holds for a thread that is going away.
 * Left alone they would hang until the caller's socket died. */
private rejectPendingSends(record: ThreadRecord, reason: string): void {
  const abandoned = record.pendingSends.splice(0, record.pendingSends.length);
  for (const pending of abandoned) pending.reject(new Error(reason));
  if (!record.admittingSend) return;
  // This one is already inside Pi's `prompt()` and cannot be recalled, so
  // the run it is about to start is aborted as soon as it exists.
  record.pendingStop = true;
  record.admittingSend.reject(new Error(reason));
}

/**
 * Stop the whole logical run, and say whether it actually stopped.
 *
 * Aborting the agent alone left Pi's recovery running: an overflow
 * compaction and a retry backoff each have their own controller, so Stop
 * appeared to do nothing while the run carried on.
 *
 * A prompt inside Pi's PREFLIGHT cannot be stopped at all. Verified against
 * Pi 0.84.1: `PromptOptions` carries no `AbortSignal`, `Agent.abort()` only
 * aborts `activeRun` — which does not exist yet — and `waitForIdle()`
 * returns at once because Pi calls itself idle throughout. So Stop reports
 * `stopped: false` rather than claiming a stop that did not happen: the
 * thread stays busy, its prompt stays in the queue, and the run that prompt
 * turns into is aborted the moment it exists.
 *
 * Everything is decided BEFORE the first await. `session.abort()` waits for
 * settlement, and Pi drains a queued continuation on the way there, so a
 * prompt can leave its hook, queue, run and finish inside that one await —
 * arming afterwards armed nothing, and reading `admittingSend` afterwards
 * reported a clean stop for a prompt that had already answered.

}

