function getFlameTexture() {
  if (cachedFlameTexture) return cachedFlameTexture;
  const width = 32;
  const height = 256;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0.0, 'rgba(255,255,255,0)');
  gradient.addColorStop(0.35, 'rgba(255,255,255,0.45)');
  gradient.addColorStop(0.75, 'rgba(255,255,255,0.95)');
  gradient.addColorStop(1.0, 'rgba(255,255,255,1)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, width, height);
  cachedFlameTexture = new THREE.CanvasTexture(canvas);
  cachedFlameTexture.colorSpace = THREE.SRGBColorSpace;
  return cachedFlameTexture;
}

function createFlameGeometry() {
  const geometry = new THREE.ConeGeometry(1, 1, 18, 1, true);
  geometry.translate(0, 0.5, 0);
  geometry.rotateX(Math.PI / 2);
  return geometry;
}

function createFlameMesh(color) {
  const material = new THREE.MeshBasicMaterial({
    map: getFlameTexture(),
    color,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(createFlameGeometry(), material);
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  return mesh;
}

