// Patches every lit car material so fragments below WATER_LEVEL in world space
// are tinted toward the underwater color: a crisp edge right at the waterline
// that deepens with submerged depth. A shared `uInWater` uniform gates the whole
// effect off until the car is actually over a broken lake. The additive exhaust
// flame (basic material) is left untouched.
export function createUnderwaterTint(car) {
  const inWater = { value: 0 };
  const seen = new Set();
  car.traverse((child) => {
    if (!child.isMesh) return;
    const materials = Array.isArray(child.material) ? child.material : [child.material];
    for (const material of materials) {
      if (material.isMeshBasicMaterial || seen.has(material)) continue;
      seen.add(material);
      patchWaterline(material, inWater);
    }
  });
  return function updateUnderwaterTint(carInWater) {
    inWater.value = carInWater ? 1 : 0;
  };
}

function patchWaterline(material, inWater) {
  material.onBeforeCompile = (shader) => {
    shader.uniforms.uInWater = inWater;
    shader.uniforms.uWaterLevel = { value: WATER_LEVEL };
    shader.uniforms.uTintColor = { value: new THREE.Color(UNDERWATER_TINT_COLOR) };
    shader.uniforms.uTintMax = { value: UNDERWATER_TINT_MAX };
    shader.uniforms.uTintDepth = { value: UNDERWATER_TINT_DEPTH };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nvarying float vWorldY;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvWorldY = (modelMatrix * vec4(transformed, 1.0)).y;');
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>
varying float vWorldY;
uniform float uInWater;
uniform float uWaterLevel;
uniform vec3 uTintColor;
uniform float uTintMax;
uniform float uTintDepth;`)

