function createSandGrainTexture() {
  const size = DUST_TEXTURE_SIZE;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  const center = size / 2;
  const maxR = size / 2;

  const baseGradient = ctx.createRadialGradient(center, center, 0, center, center, maxR);
  baseGradient.addColorStop(0.0, 'rgba(255,255,255,0.55)');
  baseGradient.addColorStop(0.45, 'rgba(255,255,255,0.3)');
  baseGradient.addColorStop(0.8, 'rgba(255,255,255,0.08)');
  baseGradient.addColorStop(1.0, 'rgba(255,255,255,0)');
  ctx.fillStyle = baseGradient;
  ctx.fillRect(0, 0, size, size);

  for (let i = 0; i < DUST_GRAIN_COUNT; i++) {
    const r = Math.sqrt(Math.random()) * maxR;
    const theta = Math.random() * Math.PI * 2;
    const x = center + Math.cos(theta) * r;
    const y = center + Math.sin(theta) * r;
    const grainRadius = Math.pow(Math.random(), 2.2) * 4.0 + 0.5;
    const radialFalloff = Math.pow(1 - r / maxR, 0.85);
    const alpha = radialFalloff * (0.5 + Math.random() * 0.4);
    const tone = 210 + Math.floor(Math.random() * 45);
    ctx.fillStyle = `rgba(${tone},${tone},${tone},${alpha.toFixed(3)})`;
    ctx.beginPath();
    ctx.arc(x, y, grainRadius, 0, Math.PI * 2);
    ctx.fill();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

