};

const DRIVE_ACTIONS = ['f', 'b', 'l', 'r'];

export function createInput(audioController) {
  const keys = { f: false, b: false, l: false, r: false, space: false, jump: false };
  const heldKeyboardCodes = {
    f: new Set(),
    b: new Set(),
    l: new Set(),
    r: new Set(),
  };
  const touchDrive = { f: false, b: false, l: false, r: false };
  let activePointerId = null;

  function syncDriveAction(action) {
    keys[action] = heldKeyboardCodes[action].size > 0 || touchDrive[action];
  }

  function syncDriveActions() {
    for (const action of DRIVE_ACTIONS) syncDriveAction(action);
  }

  function setKeyboardDriveState(event, pressed) {
    const action = DRIVE_ACTION_BY_CODE[event.code];
    if (!action) return;

    if (event.code.startsWith('Arrow')) event.preventDefault();
    if (pressed) heldKeyboardCodes[action].add(event.code);
    else heldKeyboardCodes[action].delete(event.code);
    syncDriveAction(action);
  }

  function resetInput() {
    for (const action of DRIVE_ACTIONS) {
      heldKeyboardCodes[action].clear();
      touchDrive[action] = false;
    }
    syncDriveActions();
    keys.space = false;
    keys.jump = false;
    activePointerId = null;
  }

  window.addEventListener('keydown', (event) => {
    audioController.enable();
    setKeyboardDriveState(event, true);
    if (event.code === 'Space') { keys.space = true; event.preventDefault(); }
    if (event.code === 'KeyZ') keys.jump = true;
    if (event.key === 'r' || event.key === 'R') location.reload();
  });

