export function courseStats() {
  let minX = Infinity;
  let maxX = -Infinity;
  let minZ = Infinity;
  let maxZ = -Infinity;

  for (const sample of COURSE.samples) {
    if (sample.x < minX) minX = sample.x;
    if (sample.x > maxX) maxX = sample.x;
    if (sample.z < minZ) minZ = sample.z;
    if (sample.z > maxZ) maxZ = sample.z;
  }

  return {
    length: COURSE.length,
    samples: COURSE.samples.length,
    controls: COURSE.points.length,
    minX,
    maxX,
    minZ,
    maxZ,
  };
}

