describe("namesCommand", () => {
  it("recognizes a command, with and without arguments", () => {
    expect(namesCommand(commands, "/compact")).toBe(true);
    expect(namesCommand(commands, "/compact everything older than May")).toBe(
      true,
    );
    expect(namesCommand(commands, "  /skill:retention")).toBe(true);
  });

  it("leaves a question that merely starts with a slash alone", () => {
    // The list is the authority, not the shape of the text. Blocking every
    // leading slash would block a perfectly ordinary first message.
    expect(namesCommand(commands, "/how many customers churned")).toBe(false);
    expect(namesCommand(commands, "compact")).toBe(false);
    expect(namesCommand(commands, "")).toBe(false);
  });

  it("does not match a longer name that starts the same way", () => {
    expect(namesCommand(commands, "/compactnow")).toBe(false);
  });
});

describe("blockFirstMessage", () => {
  it("blocks a real command once discovery has answered", () => {
    expect(blockFirstMessage(commands, "ready", "/compact")).toBe(true);
    expect(blockFirstMessage(commands, "ready", "/not-a-command")).toBe(false);
  });

  it("fails CLOSED on anything slash-shaped while discovery is loading", () => {
    // The defect: the provider started with an empty list and swallowed the
    // fetch error, so `namesCommand([], "/noop")` was false and a real command
    // reached createThread in the window before the fetch landed.
    expect(blockFirstMessage([], "loading", "/noop")).toBe(true);
    expect(blockFirstMessage([], "failed", "/noop")).toBe(true);
    expect(blockFirstMessage([], "loading", "  /noop with args")).toBe(true);
  });

  it("leaves an ordinary question alone in every discovery state", () => {
    for (const discovery of ["loading", "ready", "failed"] as const) {
      expect(
        blockFirstMessage(commands, discovery, "how many customers churned"),
      ).toBe(false);
    }
  });
