/**
 * Write a Pi session file straight into a store.
 *
 * Two seam claims need a session the app could not have created: one saved on a
 * provider that has no credentials (Pi's resume fallback), and one started in
 * another directory (workspace confinement). Both exist on disk in a migrated
 * store, so planting the file is the honest reproduction.
 *
 * usage: node plant-session.mjs <sessions-dir> <id> <cwd> [provider modelId]
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";

const [dir, id, cwd, provider, modelId] = process.argv.slice(2);
if (!dir || !id || !cwd) {
  console.error(
    "usage: plant-session.mjs <sessions-dir> <id> <cwd> [provider modelId]",
  );
  process.exit(2);
}

const at = new Date().toISOString();
const lines = [
  { type: "session", version: 3, id, timestamp: at, cwd },
  {
    type: "message",
    id: "e-user",
    parentId: null,
    timestamp: at,
    message: { role: "user", content: `planted ${id}`, timestamp: Date.now() },
  },
];
if (provider && modelId) {
  lines.push({
    type: "model_change",
    id: "e-model",
    parentId: "e-user",
    timestamp: at,
    provider,
    modelId,
  });
}

const file = join(dir, `${at.replace(/[:.]/g, "-")}_${id}.jsonl`);
writeFileSync(file, lines.map((line) => JSON.stringify(line)).join("\n") + "\n");
process.stdout.write(file);

