// Depth of the car's contact point below the still-water line, but only where
// there is open water to be in (a broken lake). ≤ 0 means the contact point is
// above the surface, or there's no open water here. This is what "the car is in
// the water" actually means — not "the footprint overlaps a broken lake" — so a
// break-through, a drive-in off the shore, and a plunge from the air all reduce
// to the same crossing.
export function carWaterDepth(carRig) {
  const lake = findLakeAt(carRig.position.x, carRig.position.z);
  if (!lake || !lake.broken) return -Infinity;
  return WATER_LEVEL - (carRig.position.y - CAR_Y);
}

// Single source of truth for water contact, updated each frame after the car's
// position is final. `justEnteredWater` is the rising edge — the one frame the
// contact point crosses below the surface — which every "hit the water" reaction
// keys off, regardless of how the car arrived.
export function updateWaterContact(carRig, driveState) {
  const inWater = carWaterDepth(carRig) > 0;
  driveState.justEnteredWater = inWater && !driveState.inWater;
  driveState.inWater = inWater;
}

// True while the car sits over a lake whose ice has broken — i.e. it's in open
