const providedSeed = typeof window !== 'undefined' && Number.isFinite(window.__terrainSeed)
  ? window.__terrainSeed
  : Math.floor(Math.random() * 100000);

export const TERRAIN_SEED = providedSeed;

export function seedToUint32(salt = 0) {
  const scaledSeed = Math.floor(Math.abs(TERRAIN_SEED) * 1000000);
  return (scaledSeed ^ salt ^ 0x9e3779b9) >>> 0;
}

export function createSeededRandom(salt = 0) {
  let state = seedToUint32(salt);

  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

