export function createInput(audioController) {
  const keys = { f: false, b: false, l: false, r: false, space: false };

  function setDriveKeyState(key, pressed) {
    if (key === 'ArrowUp') keys.f = pressed;
    else if (key === 'ArrowDown') keys.b = pressed;
    else if (key === 'ArrowLeft') keys.l = pressed;
    else if (key === 'ArrowRight') keys.r = pressed;
  }

  window.addEventListener('keydown', (e) => {
    audioController.enable();
    setDriveKeyState(e.key, true);
    if (e.code === 'Space') { keys.space = true; e.preventDefault(); }
    if (e.key === 'r' || e.key === 'R') location.reload();
  });
  window.addEventListener('keyup', (e) => {
    setDriveKeyState(e.key, false);
    if (e.code === 'Space') keys.space = false;
  });
  // Touch drive: the whole screen is a 2D joystick. The left/right 25% bands
  // steer, the bottom 25% band reverses, and anywhere else just accelerates
  // straight. Bands combine in the corners (bottom-left = reverse + left).
  // Forward is implied whenever you're not in the reverse band, so a single
  // finger held down always drives — drag it around to change direction.
  function applyTouchDrive(clientX, clientY) {
    keys.l = clientX < window.innerWidth * 0.25;
    keys.r = clientX > window.innerWidth * 0.75;
    keys.b = clientY > window.innerHeight * 0.75;
    keys.f = !keys.b;
  }

  function releaseTouchDrive() {
    keys.f = keys.b = keys.l = keys.r = false;
  }

  let activePointerId = null;
  window.addEventListener('pointerdown', (e) => {
    audioController.enable();
    if (e.pointerType === 'mouse') return;
    activePointerId = e.pointerId;
    applyTouchDrive(e.clientX, e.clientY);
    e.preventDefault();
  });
  window.addEventListener('pointermove', (e) => {
    if (e.pointerId !== activePointerId) return;
    applyTouchDrive(e.clientX, e.clientY);
  });
  function endTouchDrive(e) {
    if (e.pointerId !== activePointerId) return;
    activePointerId = null;
    releaseTouchDrive();
  }
  window.addEventListener('pointerup', endTouchDrive);
  window.addEventListener('pointercancel', endTouchDrive);

  return { keys };
}

import * as THREE from 'three';
import {
  KEY_SIDE_OFFSET, KEY_HOVER_HEIGHT, KEY_BOB_AMPLITUDE, KEY_BOB_SPEED, KEY_SPIN_SPEED,
  KEY_GOLD_COLOR, KEY_SHAFT_LENGTH, KEY_SHAFT_RADIUS, KEY_BOW_RADIUS, KEY_BOW_TUBE,
  KEY_BIT_WIDTH, KEY_BIT_HEIGHT, KEY_BIT_DEPTH,
} from './config.js';
import { surfaceHeightAt } from './terrain.js';
import { makeLambert, roundedBox, shadowed } from './utils.js';

const HALF_SHAFT = KEY_SHAFT_LENGTH / 2;

function buildKey() {
  const goldMat = makeLambert(KEY_GOLD_COLOR);
  const group = new THREE.Group();

  // Shaft laid along x; the round bow is the grip at one end, the teeth at the other.
  const shaftGeom = new THREE.CylinderGeometry(KEY_SHAFT_RADIUS, KEY_SHAFT_RADIUS, KEY_SHAFT_LENGTH, 10);
  shaftGeom.rotateZ(Math.PI / 2);
  group.add(shadowed(new THREE.Mesh(shaftGeom, goldMat)));

  const bow = shadowed(new THREE.Mesh(new THREE.TorusGeometry(KEY_BOW_RADIUS, KEY_BOW_TUBE, 10, 20), goldMat));
  bow.position.x = -HALF_SHAFT - KEY_BOW_RADIUS * 0.6;
  group.add(bow);

  for (const offset of [0, KEY_BIT_WIDTH * 1.8]) {
    const tooth = shadowed(new THREE.Mesh(roundedBox(KEY_BIT_WIDTH, KEY_BIT_HEIGHT, KEY_BIT_DEPTH, { radius: 0.02 }), goldMat));
    tooth.position.set(HALF_SHAFT - KEY_BIT_WIDTH - offset, -KEY_BIT_HEIGHT / 2 + KEY_SHAFT_RADIUS, 0);
    group.add(tooth);
  }

  return group;
}

export function createKey(scene, chest) {
  const x = chest.x + chest.normalX * KEY_SIDE_OFFSET;
  const z = chest.z + chest.normalZ * KEY_SIDE_OFFSET;
  const baseY = surfaceHeightAt(x, z) + KEY_HOVER_HEIGHT;

  const key = buildKey();
  key.position.set(x, baseY, z);
  scene.add(key);

  return {
    x,
    z,
    collect: () => { key.visible = false; },
    updateKey: (elapsed) => {
      if (!key.visible) return;
      key.position.y = baseY + Math.sin(elapsed * KEY_BOB_SPEED) * KEY_BOB_AMPLITUDE;
      key.rotation.y = elapsed * KEY_SPIN_SPEED;
    },
  };
}

