// The chase camera's pose: parked behind the car at CAM_OFFSET, looking ahead.
function computeFollowPose(carRig, driveState) {
  const offset = CAM_OFFSET.clone().applyAxisAngle(yAxis, driveState.heading);
  followPosition.copy(carRig.position).add(offset);
  followLook.set(
    carRig.position.x - Math.sin(driveState.heading) * 22,
    carRig.position.y + 3.3,
    carRig.position.z - Math.cos(driveState.heading) * 22,
  );
}

// The camera y required to keep the camera itself — and its sight line to the
// truck — above the terrain plus clearance. Each interior sample solves
// lineY(t) = camY·(1−t) + aimY·t ≥ ground(t) for camY: the closer an
// obstruction sits to the camera, the more lift it demands.
function clearanceCameraY(carRig, cameraX, cameraZ) {
  let required = heightAt(cameraX, cameraZ) + CAM_TERRAIN_CLEARANCE;
  const aimY = carRig.position.y + CAM_TRUCK_AIM_LIFT;
  for (let sample = 1; sample <= CAM_SIGHT_SAMPLES; sample++) {
    const sightLineFraction = sample / (CAM_SIGHT_SAMPLES + 1);
    const x = THREE.MathUtils.lerp(cameraX, carRig.position.x, sightLineFraction);
    const z = THREE.MathUtils.lerp(cameraZ, carRig.position.z, sightLineFraction);
    const ground = heightAt(x, z) + CAM_TERRAIN_CLEARANCE;
    required = Math.max(
      required,
      (ground - aimY * sightLineFraction) / (1 - sightLineFraction),
    );
  }
  return required;
}

export function updateCamera(camera, carRig, driveState, dt) {
  computeFollowPose(carRig, driveState);

  // Rise fast when the follow pose would sink into a dune, settle back slowly
  // once it clears — the asymmetry keeps rolling crests from pumping the camera.
  const clearanceY = clearanceCameraY(carRig, followPosition.x, followPosition.z);
  const liftTarget = Math.max(0, clearanceY - followPosition.y);
  const dampRate = liftTarget > terrainLift ? CAM_RISE_DAMP : CAM_RETURN_DAMP;
  terrainLift = THREE.MathUtils.damp(terrainLift, liftTarget, dampRate, dt);

