/// let metrics = CellMetrics::for_version(None);
/// assert_eq!(rule("f1", 20, &metrics), "──────── f1 ────────");
/// assert_eq!(rule("a", 20, &metrics), "──────── a ─────────");
/// assert_eq!(rule("", 20, &metrics), "────────────────────");
/// ```
pub fn rule(title: &str, width: usize, metrics: &CellMetrics) -> String {
    let filler = '─';
    if title.is_empty() {
        return std::iter::repeat_n(filler, width).collect();
    }
    let truncate_width = width.saturating_sub(4);
    if truncate_width == 0 {
        return std::iter::repeat_n(filler, width).collect();
    }
    let title = truncate_to_cells(title, truncate_width, metrics);
    let padded = metrics.cell_len(&title) + 2;
    let remaining = width.saturating_sub(padded);
    let left = remaining / 2;
    let right = remaining - left;
    format!(
        "{} {title} {}",
        std::iter::repeat_n(filler, left).collect::<String>(),
        std::iter::repeat_n(filler, right).collect::<String>(),
    )
}

/// Truncate to `limit` cells, ending in `…` when anything was dropped.
///
/// The ellipsis occupies one of the `limit` cells, which is why the kept text is
/// measured against `limit - 1` rather than `limit`.
fn truncate_to_cells(text: &str, limit: usize, metrics: &CellMetrics) -> String {
    if metrics.cell_len(text) <= limit {
        return text.to_string();
    }
    let mut kept = String::new();
    let mut cells = 0usize;
    for character in text.chars() {
        let size = metrics.character_cell_size(character);
        if cells + size > limit.saturating_sub(1) {
            break;
        }
        cells += size;
        kept.push(character);
    }
    kept.push('…');
    kept
}

