import Foundation

struct RecordingResult: Decodable {
    let findings: [String]
    let transcript: String
}

struct RecordingClient {
    let serverURL: URL

    func uploadRecording(at fileURL: URL, sharedSecret: String) async throws -> RecordingResult {
        let boundary = "Boundary-\(UUID().uuidString)"
        let audioData = try Data(contentsOf: fileURL)
        var request = URLRequest(url: serverURL.appendingPathComponent("recordings"))
        request.httpMethod = "POST"
        request.setValue(sharedSecret, forHTTPHeaderField: "X-Auth-Secret")
        request.setValue("multipart/form-data; boundary=\(boundary)", forHTTPHeaderField: "Content-Type")
        request.httpBody = multipartBody(audioData: audioData, filename: fileURL.lastPathComponent, boundary: boundary)

        let (data, response) = try await URLSession.shared.data(for: request)
        guard let httpResponse = response as? HTTPURLResponse else {
            throw RecordingClientError.invalidResponse
        }
        guard 200..<300 ~= httpResponse.statusCode else {
            throw RecordingClientError.server(statusCode: httpResponse.statusCode)
        }
        return try JSONDecoder().decode(RecordingResult.self, from: data)
    }

    private func multipartBody(audioData: Data, filename: String, boundary: String) -> Data {
        var body = Data()
        body.append("--\(boundary)\r\n")
        body.append("Content-Disposition: form-data; name=\"file\"; filename=\"\(filename)\"\r\n")
        body.append("Content-Type: audio/mp4\r\n\r\n")
        body.append(audioData)
        body.append("\r\n--\(boundary)--\r\n")
        return body
    }
}

private enum RecordingClientError: Error {
    case invalidResponse
    case server(statusCode: Int)
}

private extension Data {
    mutating func append(_ string: String) {
        append(Data(string.utf8))
    }
}

