const server = http.createServer(async (req, res) => {
  try {
    if (req.method === "OPTIONS") { res.writeHead(204, CORS); return res.end(); }
    const url = new URL(req.url, "http://x");
    const p = url.pathname;

    if (req.method === "GET" && p === "/api/health") {
      // running = sessions mid-turn (streaming an answer); restarting aborts these. live = sessions
      // loaded in memory (idle ones resume from jsonl on reconnect, so a restart is non-disruptive).
      const running = [...live.values()].filter((e) => e.session.isStreaming).length;
      return json(res, 200, { ok: true, cwd: CWD, live: live.size, running });
    }

    if (req.method === "GET" && p === "/api/sessions") {
      const infos = await listSm();
      const owners = ownerBySession();
      return json(res, 200, infos.map((s) => ({ id: s.id, firstMessage: s.firstMessage, name: s.name ?? null, path: s.path, by: owners.get(s.id) ?? null })));
    }
    if (req.method === "POST" && p === "/api/sessions") {
      const entry = await newSession(iapUser(req));
      return json(res, 200, { id: entry.session.sessionId });
    }
    if (req.method === "GET" && p === "/api/commands") return json(res, 200, listCommands());
    if (req.method === "GET" && p === "/api/files") return json(res, 200, listFiles(url.searchParams.get("q") || ""));

    // Per-session artifact desk (matched before the generic /api/sessions/:id/:action route below).
    // Listing/download read the filesystem directly, so they don't force the session to be live.
    const artList = p.match(/^\/api\/sessions\/([^/]+)\/artifacts$/);
    if (artList && req.method === "GET") return json(res, 200, listArtifacts(decodeURIComponent(artList[1])));
    const artDl = p.match(/^\/api\/sessions\/([^/]+)\/artifacts\/download$/);
    if (artDl && req.method === "GET") {
      const dlId = decodeURIComponent(artDl[1]);
      const dlPath = url.searchParams.get("path") || "";
      // Unmask only from the two download routes, only when the flag is on. Every other route
      // (prompt/events/messages/feedback) never touches the daemon — chat stays PII-free forever.
      if (UNMASK_ENABLED && url.searchParams.get("unmask") === "1") {
        const real = resolveArtifactRealPath(dlId, dlPath);
        if (!real) { res.writeHead(404, CORS); return res.end("not found"); }
        return proxyUnmask(req, res, real);
      }
      return streamArtifact(res, dlId, dlPath);
    }

    // The daily call list: one stable IAP-gated URL over a nightly-regenerated file. Same download
    // shape and the same unmask seam as an artifact, with no session in the picture.
    if (req.method === "GET" && p === "/api/daily/latest.csv") {
      const daily = resolveDailyList();
      if (!daily) {
        res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8", ...NO_STORE, ...CORS });
        return res.end("הרשימה היומית עדיין לא מוכנה");

