/**
 * A refused send, said out loud and handed its draft back.
 *
 * The composer empties itself BEFORE it hands a message over, and the core
 * then swallows what comes back (`sendTask.catch(() => {})`); the Pi runtime
 * drops its optimistic message on the way past. So a send the server refuses
 * used to take the user's prompt with it and explain nothing at all.
 *
 * What comes back is therefore the ATTEMPT, not a reading of the composer:
 * `onSendFailed` carries the text and the attachments as they went out, and
 * names the chat that sent them. Reading the live composer instead pasted
 * whatever the user had typed while the refusal was in flight and lost the
 * images outright; inferring the owner from whichever chat was open pasted one
 * chat's draft into another.
 *
 * The refusal a real user meets is a command typed as a chat's FIRST message.
 * The `/` menu is a lower bound on what Pi accepts — Pi registers commands
 * while it builds the session — so a command the menu cannot see passes the
 * pre-send block and is refused over HTTP instead.
 *
 * The surface stays scoped to a chat that does not exist yet. With no thread
 * there is no controller to load, no queue and nothing to cancel, so the reason
 * shown is certainly the send's; on a thread that exists the same refusal would
 * have to share the notice with a run's own errors, which is a product call and
 * not this one. Ownership is what keeps the scope honest either way.
 *
 * The reason rides the same notice surface as a stop report, because it
 * answers the same question — what happened to the thing I just asked for.
 * The draft goes back through `restoreComposerSend`, which is
 * `restoreComposerText` plus the images, so a refused send keeps the contract a
 * Stop keeps: nothing a user typed disappears without landing in the composer.
 */
export const PiSendRefusalProvider: FC<{
  /** The open chat, or `undefined` for one that does not exist yet. */
  threadId: string | undefined;
  refusal: PiSendRefusal | undefined;
  /** Called once the draft is back in the composer, so the holder can retire
   * the refusal. Consumption is the ONLY thing that retires one: a refusal
   * that lands while the user is in another chat has to survive however many
   * chats they visit before returning to the one it belongs to. */
  onConsumed: () => void;
  children: ReactNode;
}> = ({ threadId, refusal, onConsumed, children }) => {

