/**
 * Wires the browser `PiClient` (HTTP/SSE over `/api/pi`) into a Pi runtime. The
 * client is stable for the app's lifetime. No `workspacePath` is sent: the
 * server owns the one it serves. Image attachments ride along as Pi
 * `ImageContent` (the adapter's data URLs pass through `buildPiSendInput`).
 */
export function PiRuntimeProvider({
  isSendDisabled,
  onThreadIdChange,
  onSendFailed,
  children,
}: {
  /** Blocks sending up front (the input stays usable) — used when the open
   * thread, or the server handshake, reports a runtime that cannot run a turn. */
  isSendDisabled?: boolean | undefined;
  /** The settled id of the open thread, so the page can tell whose readiness it
   * is reading. `undefined` while a new thread is still optimistic. */
  onThreadIdChange?: ((threadId: string | undefined) => void) | undefined;
  /** A send that did not get through, with the attempt itself. Without it a
   * rejected send is dropped on the floor: the composer has already cleared and
   * the core swallows the rejection, so the user's prompt disappears and
   * nothing says why. It carries the attempt because by now the composer holds
   * whatever was typed since, and the converted attachments are gone. */
  onSendFailed?: ((failure: PiSendFailure) => void) | undefined;
  children: ReactNode;
}) {
  const client = useMemo(() => createPiHttpClient(), []);
  const adapters = useMemo(
    () => ({ attachments: new SimpleImageAttachmentAdapter() }),
    [],
  );
  const runtime = usePiRuntime({
    client,
    adapters,
    isSendDisabled: isSendDisabled ?? false,
    ...(onThreadIdChange ? { onThreadIdChange } : {}),
    ...(onSendFailed ? { onSendFailed } : {}),
  });

  return (
    <AssistantRuntimeProvider runtime={runtime}>
      {children}
    </AssistantRuntimeProvider>
  );
}

