// Project Pi-SDK agent state into assistant-ui `ThreadMessageLike[]`.
//
// Pi is the source of truth: `session.messages` holds committed history and
// `session.agent.state.streamingMessage` holds the in-flight partial. We snapshot
// both and translate Pi's message/content shapes into assistant-ui message parts.
// Tool results (separate `toolResult` messages in Pi) are folded back onto the
// matching assistant `tool-call` part, which is what assistant-ui wants to render.
//
// Pi content blocks we handle:
//   assistant: { type:"text", text } | { type:"thinking", thinking } | { type:"toolCall", id, name, arguments }
//   user:      string | [{ type:"text", text } | { type:"image", ... }]
//   toolResult:{ role:"toolResult", toolCallId, toolName, content:[...], isError }

function textOf(content) {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .filter((b) => b && (b.type === "text" || typeof b.text === "string"))
    .map((b) => b.text ?? "")
    .join("");
}

function resultText(content) {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .map((b) => (typeof b === "string" ? b : b?.text ?? (b?.type ? `[${b.type}]` : "")))
    .join("\n");
}

// One assistant Pi message -> ordered assistant-ui parts (text / reasoning / tool-call).
function assistantParts(message) {
  const blocks = Array.isArray(message.content) ? message.content : [{ type: "text", text: String(message.content ?? "") }];
  const parts = [];
  for (const b of blocks) {
    if (!b) continue;
    if (b.type === "text") parts.push({ type: "text", text: b.text ?? "" });
    else if (b.type === "thinking") parts.push({ type: "reasoning", text: b.thinking ?? b.text ?? "" });
    else if (b.type === "toolCall") {
      const args = b.arguments ?? b.args ?? {};
      parts.push({
        type: "tool-call",
        toolCallId: b.id ?? b.toolCallId,
        toolName: b.name ?? b.toolName ?? "tool",
        args,
        argsText: safeJson(args),
      });
    }
  }
  return parts;
}

function safeJson(v) {
  try {
    return JSON.stringify(v, null, 2);
  } catch {
    return String(v);
  }
}

