#!/usr/bin/env node
/**
 * Start a service in its own session and print its pid.
 *
 * `cmd &` from a shell script is not enough: the service has to outlive the
 * shell that launched it, because a scenario hands the URL back to a caller
 * whose shell is already gone. `detached: true` calls setsid(2), which also
 * makes the child a process-group leader — so stopping it later can signal the
 * whole group (`kill -- -pid`) and reach the children a dev server spawns,
 * without going near anything the harness does not own.
 *
 * usage: node spawn-detached.mjs <log-path> <command> [args...]
 */
import { spawn } from "node:child_process";
import { openSync } from "node:fs";

const [logPath, command, ...args] = process.argv.slice(2);
if (!logPath || !command) {
  console.error("usage: spawn-detached.mjs <log-path> <command> [args...]");
  process.exit(2);
}

const log = openSync(logPath, "a");
const child = spawn(command, args, {
  detached: true,
  stdio: ["ignore", log, log],
});
child.unref();
process.stdout.write(String(child.pid));

