// Serve a resolved downloadable file: optional enrichment (unmask=1, flag-gated), then the
// optional terminal xlsx conversion (as=xlsx, CSVs only) — strictly in that order.
async function sendDownload(req, res, real, { unmask, asXlsx }, extraHeaders = {}) {
  let buffer, statHeaders = {};
  if (unmask && UNMASK_ENABLED) {
    const got = await unmaskBytes(req, real);
    if (got.error) { res.writeHead(got.error, CORS); return res.end(got.message); }
    buffer = got.buffer;
    statHeaders = got.unmaskHeaders;
  } else {
    buffer = fs.readFileSync(real);
  }
  let name = path.basename(real);
  let contentType = MIME[path.extname(real)] || "application/octet-stream";
  if (asXlsx && name.toLowerCase().endsWith(".csv")) {
    buffer = await convertCsvToXlsx(buffer);
    name = name.replace(/\.csv$/i, ".xlsx");
    contentType = MIME[".xlsx"];
  }
  res.writeHead(200, {
    "Content-Type": contentType,
    "Content-Length": buffer.length,
    "Content-Disposition": attachmentDisposition(name),
    ...statHeaders,
    ...extraHeaders,
    ...CORS,
  });
  res.end(buffer);
}

