# Clinic desktop client (Windows): polls the server, copies findings to the
# clipboard, opens them in Notepad, and acks only after the copy succeeds.
# Configure the two values below before installing.
$ServerUrl = "http://CONFIGURE-ME:8741"
$SharedSecret = "CONFIGURE-ME"

$Headers = @{ "X-Auth-Secret" = $SharedSecret }

function Write-Log($Message) {
    Write-Host "$(Get-Date -Format 'HH:mm:ss') $Message"
}

while ($true) {
    try {
        $response = Invoke-WebRequest -Uri "$ServerUrl/findings/next" -Headers $Headers -UseBasicParsing

        if ($response.StatusCode -eq 200) {
            # Decode raw bytes as UTF-8: PowerShell 5.1 otherwise falls back to Latin-1 and garbles Hebrew.
            $json = [Text.Encoding]::UTF8.GetString($response.RawContentStream.ToArray())
            $item = $json | ConvertFrom-Json
            Set-Clipboard -Value $item.text

            $findingsFile = Join-Path $env:TEMP "dr-neumann-findings.txt"
            $item.text | Set-Content -Path $findingsFile -Encoding UTF8
            Start-Process notepad.exe $findingsFile

            Invoke-WebRequest -Uri "$ServerUrl/findings/$($item.id)/ack" -Headers $Headers -Method Post -UseBasicParsing | Out-Null
            Write-Log "copied findings item $($item.id) to clipboard and opened Notepad"
        }
    }
    catch {
        Write-Log "ERROR: $($_.Exception.Message)"
    }

    Start-Sleep -Seconds 2
}

