// Proxy an unmask download to the daemon: read the (fake) bytes of an already-resolved file, POST
// them with the original IAP JWT forwarded, stream the daemon's (real) response back as an
// attachment. The daemon — not the bridge — verifies the JWT and reads the crosswalk; the bridge
// only forwards. A missing/forged JWT is rejected by the daemon (403), surfaced here unchanged.
// Callers resolve the path themselves (each download route owns its own guard and its own 404).
async function proxyUnmask(req, res, real, extraHeaders = {}) {
  const name = path.basename(real);
  const jwt = req.headers["x-goog-iap-jwt-assertion"];
  let dres;
  try {
    dres = await fetch(`${UNMASK_DAEMON_URL}/unmask?name=${encodeURIComponent(name)}`, {
      method: "POST",
      headers: { "Content-Type": "application/octet-stream", ...(jwt ? { "x-goog-iap-jwt-assertion": String(jwt) } : {}) },
      body: fs.readFileSync(real),
    });
  } catch { res.writeHead(502, CORS); return res.end("unmask unavailable"); }
  if (dres.status === 403) { res.writeHead(403, CORS); return res.end("forbidden"); }
  if (!dres.ok) { res.writeHead(502, CORS); return res.end("unmask failed"); }
  const out = Buffer.from(await dres.arrayBuffer());
  const unmaskHeaders = {};
  for (const [key, value] of dres.headers) {
    if (key.toLowerCase().startsWith("x-unmask-")) unmaskHeaders[key] = value;
  }
  res.writeHead(200, {
    "Content-Type": dres.headers.get("content-type") || "application/octet-stream",
    "Content-Length": out.length,
    "Content-Disposition": attachmentDisposition(name),
    ...unmaskHeaders,
    ...extraHeaders,
    ...CORS,
  });
  res.end(out);
}

