export async function createSessionResourceLoader({ cwd, agentDir, sessionId }) {
  const sessionPrompt = SESSION_PROMPT_TEMPLATE.replaceAll("{{ session_id }}", sessionId);
  const loader = new DefaultResourceLoader({
    cwd,
    agentDir,
    appendSystemPromptOverride: (sharedPrompts) => [...sharedPrompts, sessionPrompt],
  });
  await loader.reload();
  return loader;
}

